{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C60", "C59", "C64", "C63", "C54", "C47", "C57", "C51", "C49", "C48", "C50", "C65", "C71", "C75", "C73", "C69", "C72"],
  "contradictory_card_ids": ["C67"],
  "prediction_basis_card_ids": ["C60", "C59", "C64", "C47", "C67", "C65", "C71", "C75", "C73", "C69", "C72"],
  "claims": [
    {
      "claim": "The query is a phenylthio-substituted captopril-like thiol ACE inhibitor; C60 identifies captopril as a PEPT1 substrate and C59 identifies the captopril-derived prodrug alacepril as a good PepT1 substrate, supporting carrier-mediated intestinal uptake for this scaffold.",
      "card_ids": ["C60", "C59"]
    },
    {
      "claim": "C64 shows that hPepT1 substrates with low predicted passive diffusion, such as enalapril and lisinopril, have significantly higher in vivo human jejunal P_eff via carrier-mediated uptake; C63 and C54 further show enalapril is a PEPT1 substrate with measurable A-B permeability, mitigating the query's low logD absorption liability.",
      "card_ids": ["C64", "C63", "C54"]
    },
    {
      "claim": "C47 shows a thiol-containing captopril-like ACE inhibitor (SQ-25868) is well absorbed (>70%) from all GI sites in rats, supporting adequate intestinal absorption for this scaffold.",
      "card_ids": ["C47"]
    },
    {
      "claim": "C57 shows enalaprilat has no active efflux (ER ~1) in intestinal tissue, and no L5 record provides affirmative gut-wall efflux evidence applicable to the query.",
      "card_ids": ["C57"]
    },
    {
      "claim": "L6 hepatic-clearance records show captopril hepatic clearance of 9.56 mL/min/kg (C67), indicating some first-pass loss but not establishing F < 20%; related ACE inhibitors show low intrinsic clearance (C65/C71/C75 enalapril, C73 quinapril, C69/C72 ramipril), so the metabolic-liability evidence does not overturn the absorption-supported high prediction.",
      "card_ids": ["C67", "C65", "C71", "C75", "C73", "C69", "C72"]
    },
    {
      "claim": "Solubility records for related ACE inhibitors (C51, C49, C48, C50) show high solubility in physiological media, supporting no dissolution limitation for the ionized carboxylate/thiol scaffold.",
      "card_ids": ["C51", "C49", "C48", "C50"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C67", "C65", "C71", "C75", "C73", "C69", "C72"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query (fentiapril-like thiol ACE inhibitor).",
    "No direct PEPT1, efflux, or hepatic-clearance assay on the query itself; captopril/alacepril/enalapril records are structural analogs.",
    "C67 is captopril, not the phenylthio-substituted query; thiol conjugation/oxidation of the query is not quantified.",
    "Rat S9/hepatocyte intrinsic-clearance records are species/assay indirect and not direct human F results.",
    "No formulation/dose-specific oral exposure data for the query."
  ],
  "decision_summary": "High prediction maintained: PEPT1-mediated uptake and >70% GI absorption of thiol ACE-inhibitor analogs support adequate intestinal absorption despite low logD; L6 hepatic-clearance records show moderate captopril clearance but low intrinsic clearance for related ACE inhibitors and do not establish F < 20%."
}

